/**
 * Token accounting for the session header.
 *
 * The bridge's `result` messages carry an empty usage object, so the numbers
 * come from each assistant message's API usage instead. Pure so it can be
 * tested without a DOM.
 */

export interface TokenUsage {
  /** Prompt tokens billed at full price. */
  input: number
  /** Prompt tokens served from (or written to) the cache. */
  cached: number
  /** Tokens generated by the model. */
  output: number
}

function asRecord(value: unknown): Record<string, unknown> | null {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : null
}

function tokenCount(value: unknown): number | null {
  return typeof value === 'number' && Number.isFinite(value) && value >= 0 ? value : null
}

/**
 * Reads the usage attached to an assistant payload. Frames put it under
 * `message.usage`; plain SDK messages keep it at the top level.
 */
export function usageFromPayload(payload: unknown): TokenUsage | null {
  const record = asRecord(payload)
  if (!record) return null
  const usage = asRecord(asRecord(record.message)?.usage) ?? asRecord(record.usage)
  if (!usage) return null

  const input = tokenCount(usage.input_tokens)
  const output = tokenCount(usage.output_tokens)
  const read = tokenCount(usage.cache_read_input_tokens)
  const created = tokenCount(usage.cache_creation_input_tokens)
  if (input === null && output === null && read === null && created === null) return null

  return { input: input ?? 0, cached: (read ?? 0) + (created ?? 0), output: output ?? 0 }
}

/** The whole prompt seen by the model, cached portion included. */
export function promptTokens(usage: TokenUsage): number {
  return usage.input + usage.cached
}

export type UsageRowKey = 'input' | 'cached' | 'output' | 'total'

export interface UsageRow {
  key: UsageRowKey
  value: number
}

/** 弹层里的分行数据：提示、缓存、输出，再加一行提示合计（含缓存）。 */
export function usageRows(usage: TokenUsage): UsageRow[] {
  return [
    { key: 'input', value: usage.input },
    { key: 'cached', value: usage.cached },
    { key: 'output', value: usage.output },
    { key: 'total', value: promptTokens(usage) },
  ]
}

/** `999` → `999`, `82_304` → `82.3k`, `2_500_000` → `2.5M`. */
export function formatTokenCount(count: number): string {
  const value = Math.round(count)
  if (value < 1000) return String(value)
  if (value < 1_000_000) return `${trimZero((value / 1000).toFixed(1))}k`
  return `${trimZero((value / 1_000_000).toFixed(1))}M`
}

function trimZero(value: string): string {
  return value.endsWith('.0') ? value.slice(0, -2) : value
}
